  static int splitArgs(String args) {
    int n = 1;
    int depth = 0;
    boolean q = false;
    for (int i = 0; i < args.length(); i++) {
      char ch = args.charAt(i);
      if (ch == '"') q = !q;
      else if (!q && ch == '(') depth++;
      else if (!q && ch == ')') depth--;
      else if (!q && depth == 0 && ch == ',') n++;
